  "use strict";

  const form = document.getElementById("contact-form");
  const formView = document.getElementById("form-view");
  const successView = document.getElementById("success-view");
  const submitBtn = document.getElementById("btn-submit");
  const btnReset = document.getElementById("btn-reset");
  const statusBanner = document.getElementById("status-banner");

  /* ── Field descriptors ── */
  const fields = [
    {
      id: "full-name",
      validate(value) {
        if (!value.trim()) return "Full name is required.";
        if (value.trim().length < 2) return "Please enter your full name.";
        return null;
      },
    },
    {
      id: "email",
      validate(value) {
        if (!value.trim()) return "Email address is required.";
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()))
          return "Please enter a valid email address.";
        return null;
      },
    },
    {
      id: "phone",
      validate(value) {
        if (!value.trim()) return null; // optional
        // Allow common formats: +1 (555) 555-5555, 555-555-5555, (555)5555555, etc.
        if (!/^[+]?[\d\s\-().]{7,20}$/.test(value.trim()))
          return "Please enter a valid phone number.";
        return null;
      },
    },
  ];

  /* ── Track whether a field has been interacted with ── */
  const touched = {};

  function getEl(id) {
    return document.getElementById(id);
  }

  function setError(fieldId, message) {
    const input = getEl(fieldId);
    const errorEl = getEl(`${fieldId}-error`);
    if (!input || !errorEl) return;

    if (message) {
      input.setAttribute("aria-invalid", "true");
      errorEl.textContent = message;
      errorEl.setAttribute("data-visible", "true");
    } else {
      input.setAttribute("aria-invalid", "false");
      errorEl.removeAttribute("data-visible");
      errorEl.textContent = "";
    }
  }

  function clearError(fieldId) {
    setError(fieldId, null);
  }

  function validateField(fieldDef) {
    const input = getEl(fieldDef.id);
    if (!input) return null;
    const error = fieldDef.validate(input.value);
    return error;
  }

  /* ── Show error only after user has touched the field ── */
  function handleBlur(fieldDef) {
    touched[fieldDef.id] = true;
    const error = validateField(fieldDef);
    setError(fieldDef.id, error);
  }

  function handleInput(fieldDef) {
    if (!touched[fieldDef.id]) return;
    const error = validateField(fieldDef);
    setError(fieldDef.id, error);
  }

  /* ── Wire up per-field events ── */
  fields.forEach((field) => {
    const input = getEl(field.id);
    if (!input) return;
    input.addEventListener("blur", () => handleBlur(field));
    input.addEventListener("input", () => handleInput(field));
  });

  /* ── Submit ── */
  form.addEventListener("submit", (e) => {
    e.preventDefault();

    // Validate all fields
    let firstInvalidId = null;
    fields.forEach((field) => {
      touched[field.id] = true;
      const error = validateField(field);
      setError(field.id, error);
      if (error && !firstInvalidId) firstInvalidId = field.id;
    });

    if (firstInvalidId) {
      // Focus first invalid field
      getEl(firstInvalidId)?.focus();
      showBanner("Please fix the errors below before submitting.", "error");
      return;
    }

    hideBanner();
    submitBtn.disabled = true;
    submitBtn.textContent = "Sending…";

    // Simulate async submission
    setTimeout(() => {
      submitBtn.disabled = false;
      submitBtn.textContent = "Send Message";
      showSuccess();
    }, 1200);
  });

  /* ── Reset / send another ── */
  btnReset.addEventListener("click", () => {
    form.reset();
    fields.forEach((f) => clearError(f.id));
    Object.keys(touched).forEach((k) => delete touched[k]);
    hideBanner();
    successView.removeAttribute("data-visible");
    formView.hidden = false;
    // Focus first field
    getEl("full-name")?.focus();
  });

  function showSuccess() {
    formView.hidden = true;
    successView.setAttribute("data-visible", "true");
    // Move focus to success heading
    document.getElementById("success-heading")?.focus();
  }

  function showBanner(message, type) {
    statusBanner.textContent = message;
    statusBanner.className = `status-banner status-banner--${type}`;
    statusBanner.setAttribute("data-visible", "true");
  }

  function hideBanner() {
    statusBanner.removeAttribute("data-visible");
    statusBanner.textContent = "";
  }
})();
