    statusBanner.textContent = message;
    statusBanner.className = `status-banner status-banner--${type}`;
    statusBanner.setAttribute("data-visible", "true");
  }

  function hideBanner() {
    statusBanner.removeAttribute("data-visible");
    statusBanner.textContent = "";
  }
