  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.form-field__label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
}

.form-field__required {
  color: var(--color-required);
  margin-left: 0.2em;
  font-weight: 700;
  aria-hidden: true;
}

.form-field__input {
  width: 100%;
  padding: 0.625rem 0.875rem;
  font-size: 0.9375rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
  min-width: 0;
}

.form-field__input::placeholder {
  color: #9ca3af;
}

.form-field__input:hover {
  border-color: #9ca3af;
}

.form-field__input:focus {
  border-color: var(--color-border-focus);
  box-shadow: var(--shadow-focus);
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.form-field__input[aria-invalid="true"] {
  border-color: var(--color-error-border);
  background: var(--color-error-bg);
}

.form-field__input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgb(185 28 28 / 0.2);
}

.form-field__helper {
  font-size: 0.8125rem;
  color: var(--color-text-subtle);
  line-height: 1.4;
}

.form-field__error {
  font-size: 0.8125rem;
  color: var(--color-error);
  font-weight: 500;
  display: none;
  align-items: center;
  gap: 0.3rem;
  line-height: 1.4;
}

.form-field__error[data-visible="true"] {
  display: flex;
}

/* ── Submit button ── */
.btn-submit {
  margin-top: 0.5rem;
  width: 100%;
  padding: 0.75rem 1.5rem;
  font-size: 0.9375rem;
  font-weight: 600;
  font-family: inherit;
  color: #fff;
  background: var(--color-primary);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition), transform var(--transition);
  outline: none;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 3px;
  box-shadow: var(--shadow-focus);
}

.btn-submit:disabled {
  opacity: 0.65;
  cursor: not-allowed;
  transform: none;
}

/* ── Required fields note ── */
.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-subtle);
  margin-bottom: 0.25rem;
}

.required-note span {
  color: var(--color-required);
  font-weight: 700;
}

/* ── Success state ── */
.success-view {
  display: none;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 1rem 0;
  gap: 1rem;
}

.success-view[data-visible="true"] {
  display: flex;
}

.success-view__icon {
  width: 56px;
  height: 56px;
  background: var(--color-success-bg);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.success-view h2 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-text);
}

.success-view p {
  color: var(--color-text-subtle);
  font-size: 0.9375rem;
  max-width: 30ch;
}

.btn-reset {
  margin-top: 0.25rem;
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--color-primary);
  background: transparent;
  border: 1.5px solid var(--color-primary);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition);
}

.btn-reset:hover {
  background: rgb(37 99 235 / 0.06);
}

.btn-reset:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* ── Reflow / responsive ── */
@media (max-width: 400px) {
  main {
    margin: 1.5rem auto;
  }
  .card {
    padding: 1.25rem 1rem;
  }
  .page-intro h1 {
    font-size: 1.375rem;
  }
}

/* ── Forced colors ── */
@media (forced-colors: active) {
  .form-field__input {
    border: 2px solid ButtonText;
    color: CanvasText;
    background: Canvas;
    forced-color-adjust: none;
  }
  .form-field__input:focus {
    outline: 2px solid Highlight;
    outline-offset: 1px;
  }
  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
    forced-color-adjust: none;
  }
  .btn-submit:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  .skip-link:focus {
    outline: 2px solid Highlight;
  }
}
